/* ===== PRODUCTS PAGE ===== */
.products-hero{padding:150px 8% 30px;background:linear-gradient(120deg,#f9fcfd,#eef8fb 56%,#fff)}
.products-hero h1{font-family:var(--head);font-weight:600;font-size:clamp(42px,5vw,64px);letter-spacing:-3px;line-height:1.05;margin:0 0 16px;color:var(--navy)}
.products-hero .lead{max-width:560px}
.products-grid-wrap{padding:20px 8% 110px}
.products-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
.product-card{border:1px solid var(--line);border-radius:18px;overflow:hidden;background:#fff;display:flex;flex-direction:column;transition:border-color .3s ease,box-shadow .3s ease}
.product-card:hover{border-color:var(--blue);box-shadow:0 18px 45px rgba(0,30,50,.08)}
.product-card-visual{height:210px;position:relative;background:linear-gradient(180deg,#f7fafb,#eef5f7);border-bottom:1px solid var(--line);overflow:hidden}
.product-card-img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
.product-card:hover .product-card-img{transform:scale(1.05)}
.product-card-shade{position:absolute;inset:0;background:linear-gradient(180deg,rgba(10,20,30,.28),transparent 45%,rgba(8,14,20,.5));z-index:1}
.product-card-tag{position:absolute;top:16px;left:16px;font-size:9px;letter-spacing:1.5px;color:#fff;font-weight:800;background:rgba(10,16,22,.55);padding:5px 11px;border-radius:20px;z-index:2;backdrop-filter:blur(3px)}
.product-card-body{padding:26px;display:flex;flex-direction:column;flex:1}
.product-card-cat{font-size:9px;letter-spacing:1.5px;color:var(--blue);font-weight:800;margin-bottom:10px}
.product-card-body h3{font-family:var(--head);font-weight:600;font-size:21px;margin:0 0 10px}
.product-card-body p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 22px;flex:1}
.product-card-cta{display:inline-flex;align-items:center;gap:8px;font-size:13px;font-weight:700;color:var(--navy);transition:color .3s ease}
.product-card-cta svg{transition:transform .3s ease}
.product-card:hover .product-card-cta{color:var(--blue)}
.product-card:hover .product-card-cta svg{transform:translate(3px,-3px)}
.products-cta{margin:0 8% 90px}
.products-cta .actions{justify-content:center}

/* ===== FIREGUARD VR ===== */
.fg-hero .hero-copy{z-index:2}
.fg-hero h1{font-size:clamp(40px,4.4vw,62px);line-height:1.02;letter-spacing:-2px;max-width:640px}
.fg-visual{position:relative;z-index:2;display:flex;flex-direction:column;gap:22px;justify-content:center}
.fg-sim-card{border:1px solid #22303a;border-radius:18px;overflow:hidden;box-shadow:0 30px 70px rgba(4,10,14,.35);background:#0c1217;width:100%;max-width:560px;justify-self:center}
.fg-sim-head{display:flex;justify-content:space-between;align-items:center;padding:13px 18px;background:#0c1217;border-bottom:1px solid #1e2a33;font-size:9px;letter-spacing:1.6px;color:#8fa3b0;font-weight:800}
.fg-sim-head span{display:flex;align-items:center;gap:7px}
.fg-dot{width:7px;height:7px;background:#FF6B35;border-radius:50%;display:inline-block}
.fg-scene{position:relative;height:260px;background:linear-gradient(180deg,#141d24 0%,#0d1419 60%,#0a0f13 100%);overflow:hidden}
.fg-hud{position:absolute;width:22px;height:22px;border:2px solid rgba(111,207,245,.55);z-index:3}
.fg-hud-tl{top:12px;left:12px;border-right:0;border-bottom:0}
.fg-hud-tr{top:12px;right:12px;border-left:0;border-bottom:0}
.fg-hud-bl{bottom:12px;left:12px;border-right:0;border-top:0}
.fg-hud-br{bottom:12px;right:12px;border-left:0;border-top:0}
.fg-scene-floor{position:absolute;left:0;right:0;bottom:0;height:30%;background:linear-gradient(180deg,rgba(32,42,51,.15),rgba(8,12,15,.6));z-index:2}
.fg-building{position:absolute;bottom:14%;width:86px;height:118px;background:#1b252d;border-radius:6px 6px 0 0;display:grid;grid-template-columns:repeat(2,1fr);gap:10px;padding:12px;z-index:1}
.fg-building i{background:#f59e0b;opacity:.5;border-radius:2px}
.fg-building-1{left:16px}
.fg-building-2{left:118px;width:64px;height:74px}
.fg-machine{position:absolute;right:16px;bottom:14%;width:74px;height:46px;background:#1f2a33;border-radius:8px;z-index:1}
.fg-machine i{position:absolute;left:10px;top:10px;width:22px;height:22px;border:2px solid #3a4a56;border-radius:50%;background:#0e1419}
.fg-machine i:nth-child(2){left:40px;top:12px;width:16px;height:20px;border:2px solid #3a4a56;border-radius:6px;background:none}
.fg-worker{position:absolute;left:38%;bottom:16%;width:54px;height:112px;z-index:4}
.fg-worker-head{position:absolute;top:0;left:10px;width:34px;height:34px;border-radius:50%;background:#202b35;display:block}
.fg-vr-band{position:absolute;top:10px;left:3px;width:28px;height:13px;border-radius:7px;background:var(--blue);display:block;box-shadow:0 0 10px rgba(19,81,216,.7)}
.fg-worker-body{position:absolute;top:38px;left:7px;width:40px;height:54px;border-radius:10px;background:#26323c;display:block}
.fg-worker-arm{position:absolute;top:54px;left:-8px;width:28px;height:8px;border-radius:6px;background:#26323c;transform:rotate(-22deg);display:block}
.fg-extinguisher{position:absolute;left:25%;bottom:15%;width:24px;height:54px;z-index:4}
.fg-ext-tank{position:absolute;bottom:0;left:2px;width:18px;height:38px;border-radius:6px;background:#EF4444;display:block;box-shadow:inset -4px 0 rgba(0,0,0,.2)}
.fg-ext-hose{position:absolute;top:2px;left:10px;width:30px;height:4px;border-radius:4px;background:#c9d4da;transform:rotate(16deg);transform-origin:left center;display:block}
.fg-fire{position:absolute;right:22%;bottom:19%;width:46px;height:64px;z-index:3;animation:fgFlicker 1.6s ease-in-out infinite alternate}
.fg-flame{position:absolute;bottom:0;border-radius:50% 50% 45% 45%;background:linear-gradient(180deg,#FF6B35,#EF4444 70%);display:block}
.fg-f1{left:4px;width:38px;height:52px}
.fg-f2{left:14px;bottom:8px;width:20px;height:40px;background:linear-gradient(180deg,#F59E0B,#FF6B35);animation-delay:.4s}
.fg-f3{left:20px;bottom:14px;width:10px;height:26px;background:linear-gradient(180deg,#ffd166,#F59E0B);animation-delay:.8s}
@keyframes fgFlicker{from{transform:scale(1) rotate(-1deg)}to{transform:scale(1.05) rotate(1.5deg)}}
.fg-reticle{position:absolute;right:20%;bottom:30%;width:74px;height:74px;z-index:5;transform:translate(8px,8px)}
.fg-reticle-ring{position:absolute;inset:0;border:1.5px solid rgba(111,207,245,.8);border-radius:50%;display:block;animation:fgPulse 1.4s ease-in-out infinite}
.fg-reticle-cross{position:absolute;background:rgba(111,207,245,.8);display:block}
.fg-rc-h{top:50%;left:-10px;width:94px;height:1.5px}
.fg-rc-v{left:50%;top:-10px;width:1.5px;height:94px}
@keyframes fgPulse{0%{transform:scale(.88);opacity:.65}100%{transform:scale(1.05);opacity:1}}
.fg-chip{position:absolute;font-size:9px;letter-spacing:1.2px;font-weight:800;padding:6px 11px;border-radius:20px;background:rgba(255,255,255,.08);color:#cfe3ff;border:1px solid rgba(111,207,245,.25);z-index:6;white-space:nowrap}
.fg-chip-step{top:16px;left:50%;transform:translateX(-50%)}
.fg-chip-ok{bottom:16px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:5px;color:#8ff0c3;border-color:rgba(97,213,173,.4);background:rgba(22,101,71,.3)}
.fg-sim-foot{display:flex;padding:12px 18px;background:#0c1217;border-top:1px solid #1e2a33;font-size:8.5px;letter-spacing:1.4px;color:#5c6f7b;font-weight:800}
.fg-sim-foot span{padding:0 10px;border-right:1px solid #1e2a33}
.fg-sim-foot span:first-child{padding-left:0}
.fg-sim-foot .fg-foot-active{color:#FF6B35}
.fg-microstats{display:grid;grid-template-columns:repeat(4,1fr);background:#fff;border:1px solid var(--line);border-radius:14px;overflow:hidden;max-width:560px;justify-self:center;width:100%}
.fg-micro{padding:16px 18px;border-right:1px solid var(--line)}
.fg-micro:last-child{border-right:0}
.fg-micro b{display:block;font-family:var(--head);font-weight:600;font-size:17px;color:var(--navy);line-height:1.2}
.fg-micro span{display:block;font-size:8.5px;letter-spacing:1.2px;color:#8a979c;font-weight:800;margin-top:6px}
.fg-challenge-grid{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--line);border:1px solid var(--line);margin-top:34px}
.fg-challenge{background:#fff;padding:20px 22px;display:flex;align-items:center;gap:14px;min-height:70px}
.fg-challenge:last-child{grid-column:1/-1;justify-content:center}
.fg-challenge-num{font-family:var(--head);color:#c3ced2;font-size:12px;font-weight:600}
.fg-challenge-icon{color:var(--blue);flex-shrink:0}
.fg-challenge b{font-size:14px;line-height:1.3}
.fg-progress{display:grid;grid-template-columns:repeat(5,1fr);gap:1px;background:var(--line);border:1px solid var(--line);margin-top:50px}
.fg-progress-item{background:#fff;padding:28px 26px;min-height:170px;display:flex;flex-direction:column;gap:16px;transition:box-shadow .3s ease}
.fg-progress-item:hover{box-shadow:0 16px 34px rgba(0,30,50,.12)}
.fg-progress-item span{font-family:var(--head);font-size:13px;color:var(--blue);font-weight:600}
.fg-progress-item b{font-size:15px;line-height:1.5;font-weight:600}
.fg-timeline{display:grid;grid-template-columns:repeat(4,1fr);gap:44px 24px;padding-top:70px}
.fg-timeline-step{position:relative;padding-top:6px}
.fg-timeline-step:not(:nth-child(4n)):after{content:'';position:absolute;top:23px;left:34px;right:-24px;height:1px;background:rgba(19,81,216,.25)}
.fg-timeline-node{width:34px;height:34px;border-radius:50%;border:1px solid var(--blue);color:var(--blue);display:grid;place-items:center;font-family:var(--head);font-weight:600;font-size:13px;background:#fff;position:relative;z-index:2;margin-bottom:18px}
.fg-timeline-step h3{font-family:var(--head);font-weight:600;font-size:17px;margin:0 0 8px}
.fg-timeline-step p{font-size:12.5px;line-height:1.6;color:var(--muted);margin:0;max-width:230px}
.fg-benefits-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:60px}
.fg-benefit{background:#fff;border:1px solid var(--line);border-radius:16px;padding:28px;position:relative;min-height:210px;transition:transform .3s ease,border-color .3s ease,box-shadow .3s ease}
.fg-benefit:hover{transform:translateY(-5px);border-color:var(--blue);box-shadow:0 16px 34px rgba(0,30,50,.12)}
.fg-benefit:hover .fg-benefit-icon{background:var(--blue);color:#fff}
.fg-benefit-icon{width:44px;height:44px;border-radius:50%;background:rgba(19,81,216,.1);color:var(--blue);display:grid;place-items:center;margin-bottom:26px}
.fg-benefit small{position:absolute;right:26px;top:28px;color:#9aa7ac;font-size:9px}
.fg-benefit h3{font-family:var(--head);font-weight:600;font-size:18px;margin:0 0 10px}
.fg-benefit p{font-size:13px;line-height:1.6;color:var(--muted);margin:0}
.fg-industry-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:56px}
.fg-industry{border:1px solid var(--line);border-radius:14px;background:#fff;padding:26px 18px;display:flex;align-items:center;gap:12px;transition:border-color .3s ease;cursor:default}
.fg-industry svg{color:#8b9ba1;transition:color .3s ease}
.fg-industry:hover{border-color:var(--blue)}
.fg-industry:hover svg{color:var(--blue)}
.fg-industry span{font-size:13px;font-weight:600}
.fg-glance{padding:110px 8% 115px;background:#1C1C1C;color:#fff}
.fg-glance h2{font-family:var(--head);font-weight:600;font-size:clamp(38px,4.6vw,60px);line-height:1.04;letter-spacing:-2.7px;margin:0}
.fg-glance-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:rgba(255,255,255,.14);margin-top:60px}
.fg-glance-cell{background:rgba(255,255,255,.07);padding:34px 26px;position:relative}
.fg-glance-cell small{font-size:9px;letter-spacing:1.5px;color:#c6d7ff;font-weight:800;display:block;margin-bottom:12px}
.fg-glance-cell b{font-family:var(--head);font-weight:600;font-size:26px;color:#fff;display:block}
.fg-glance-cell i{display:block;width:34px;height:2px;background:var(--blue);margin-top:18px}
.fg-compliance{padding:110px 8% 115px;background:#fff}
.fg-compliance h2{font-family:var(--head);font-weight:600;font-size:clamp(38px,4.6vw,60px);line-height:1.04;letter-spacing:-2.7px;margin:0}
.fg-compliance-inner{display:grid;grid-template-columns:1fr 1.1fr;gap:64px;margin-top:56px;align-items:center}
.fg-compliance-copy p{font-size:17px;line-height:1.7;color:var(--muted);max-width:520px}
.fg-compliance-list{border-top:1px solid var(--line);margin-top:28px}
.fg-compliance-item{display:flex;align-items:center;gap:14px;padding:15px 0;border-bottom:1px solid var(--line);font-weight:600;font-size:14px}
.fg-compliance-item svg{color:var(--blue)}
.fg-compliance-item span{color:#9aa7ac;font-size:10px;font-family:var(--head)}
.fg-report-card{border:1px solid var(--line);border-radius:16px;overflow:hidden;box-shadow:0 18px 50px rgba(0,30,50,.08)}
.fg-report-head{display:flex;justify-content:space-between;align-items:center;padding:15px 20px;border-bottom:1px solid var(--line);font-size:9px;letter-spacing:1.4px;color:#8a979c;font-weight:800}
.fg-report-head b{color:var(--navy)}
.fg-report-head span{display:flex;align-items:center;gap:6px}
.fg-report-row{display:grid;grid-template-columns:1.4fr .6fr .9fr 1fr .7fr 1fr;gap:8px;padding:13px 20px;border-bottom:1px solid #eef2f4;font-size:12px;align-items:center}
.fg-report-h{font-size:9px;letter-spacing:1px;color:#8a979c;font-weight:800;background:#fafcfd;text-transform:uppercase}
.fg-report-row .fg-ok{color:#10b981;font-weight:700}
.fg-report-row .fg-warn{color:#F59E0B;font-weight:700}
.fg-report-foot{display:flex;align-items:center;gap:8px;padding:14px 20px;font-size:11px;color:var(--muted)}
.fg-report-foot svg{color:var(--blue)}
.fg-cta-actions{justify-content:center}
.fg-cta-link{color:#dbe4ff;font-weight:700;display:inline-flex;align-items:center;gap:8px}
.fg-cta-link:hover{color:#fff}
.fg-cta-link svg{transition:transform .3s ease}
.fg-cta-link:hover svg{transform:translateX(4px)}

/* ===== BUS & DRIVER ===== */
.bd-visual{display:grid;place-items:center;align-content:center;gap:26px;height:520px;position:relative;z-index:2}
.bd-icon-box{width:132px;height:132px;border-radius:50%;border:1.5px solid var(--blue);display:grid;place-items:center;color:var(--blue);background:rgba(19,81,216,.06)}
.bd-note{font-size:9px;letter-spacing:2px;color:#8a979c;font-weight:800;text-align:center;line-height:1.8}

@media(max-width:1000px){
  .products-grid{grid-template-columns:1fr 1fr}
  .fg-timeline{grid-template-columns:repeat(2,1fr);gap:38px 22px}
  .fg-timeline-step:not(:nth-child(4n)):after{display:none}
  .fg-benefits-grid{grid-template-columns:repeat(2,1fr)}
  .fg-industry-grid{grid-template-columns:repeat(3,1fr)}
  .fg-glance-grid{grid-template-columns:repeat(2,1fr)}
  .fg-progress{grid-template-columns:repeat(2,1fr)}
  .fg-compliance-inner{grid-template-columns:1fr;gap:44px}
  .fg-challenge-grid{grid-template-columns:1fr 1fr}
  .bd-visual{height:430px}
}
@media(max-width:700px){
  .products-hero{padding:120px 6% 26px}
  .products-hero h1{font-size:39px;letter-spacing:-1.8px}
  .products-grid{grid-template-columns:1fr}
  .products-grid-wrap{padding:16px 6% 90px}
  .product-card-visual{height:170px}
  .fg-visual{gap:16px}
  .fg-scene{height:210px}
  .fg-progress{grid-template-columns:1fr;margin-top:34px}
  .fg-progress-item{min-height:0;padding:22px 20px}
  .fg-sim-foot{display:none}
  .fg-microstats{grid-template-columns:1fr 1fr;gap:10px;border:0;background:none;max-width:100%}
  .fg-micro{border:1px solid var(--line);border-radius:12px;padding:14px 16px}
  .fg-timeline{grid-template-columns:1fr;gap:0;padding-top:44px}
  .fg-timeline-step{position:relative;padding:0 0 32px 46px}
  .fg-timeline-step:before{content:'';position:absolute;left:16px;top:40px;bottom:4px;width:1px;background:var(--line)}
  .fg-timeline-step:last-child:before{display:none}
  .fg-timeline-node{position:absolute;left:0;top:0;margin-bottom:0}
  .fg-timeline-step p{max-width:100%}
  .fg-benefits-grid{grid-template-columns:1fr;margin-top:40px}
  .fg-benefit{min-height:0}
  .fg-challenge:last-child{grid-column:auto;justify-content:flex-start}
  .fg-industry-grid{grid-template-columns:repeat(2,1fr);gap:10px;margin-top:40px}
  .fg-industry{padding:20px 14px;flex-direction:column;align-items:flex-start;gap:8px}
  .fg-glance{padding:80px 6%}
  .fg-glance h2{font-size:39px}
  .fg-glance-grid{grid-template-columns:1fr 1fr;margin-top:40px}
  .fg-glance-cell{padding:24px 18px}
  .fg-glance-cell b{font-size:20px}
  .fg-compliance{padding:80px 6%}
  .fg-compliance h2{font-size:39px}
  .fg-compliance-inner{gap:36px;margin-top:40px}
  .fg-challenge-grid{grid-template-columns:1fr}
  .fg-cta-actions{flex-direction:column;gap:18px}
  .fg-report-row{grid-template-columns:1.4fr .8fr 1fr 1fr;padding:12px 16px}
  .fg-report-row span:nth-child(4),.fg-report-row span:nth-child(5){display:none}
  .bd-visual{height:380px}
}
